begin read only;
select jsonb_build_object('database',current_database(),'role',current_user,'financial_tables',(select count(*) from pg_tables where schemaname='public' and tablename like 'finance_%'),'finance_rpc_exists',to_regprocedure('public.finance_rpc(text,jsonb)') is not null,'connections_rows',(select count(*) from public.connections),'asaas_connections',(select count(*) from public.connections where provider='asaas'),'connections_rls',(select relrowsecurity from pg_class where oid='public.connections'::regclass),'connections_acl',(select relacl::text from pg_class where oid='public.connections'::regclass),'columns',(select jsonb_agg(jsonb_build_object('name',column_name,'type',udt_name,'nullable',is_nullable,'default',column_default) order by ordinal_position) from information_schema.columns where table_schema='public' and table_name='connections'),'constraints',(select jsonb_agg(pg_get_constraintdef(oid)) from pg_constraint where conrelid='public.connections'::regclass),'indexes',(select jsonb_agg(indexdef) from pg_indexes where schemaname='public' and tablename='connections'),'policies',(select coalesce(jsonb_agg(jsonb_build_object('name',policyname,'roles',roles,'cmd',cmd)), '[]'::jsonb) from pg_policies where schemaname='public' and tablename='connections')) as inventory;
commit;